export function computeInvoiceTotal(lines: { quantity: number; unitPrice: number }[], taxRate: number) {
  const subtotal = lines.reduce((total, line) => total + line.quantity * line.unitPrice, 0);
  return subtotal * (1 + taxRate);
}

sources.shipping/postage.ts:
export function shippingCharge(weight: number, distance: number, pricePerKilogram: number) {
  return weight * pricePerKilogram + distance * 0.02;
}

sources.accounts/login.ts:
export function recordFailedLogin(account: { attempts: number; lockedUntil: number }, now: number) {
  account.attempts += 1;
  if (account.attempts >= 3) account.lockedUntil = now + 60000;
}

sources.accounts/otp.ts:
export function verifyOneTimeCode(supplied: string, expected: string, expiresAt: number, now: number) {
  return now < expiresAt && supplied === expected;
}

sources.network/json.ts:
export async function fetchJson(url: string, signal: AbortSignal) {
  const response = await fetch(url, { signal });
  if (!response.ok) throw new Error(String(response.status));
  return response.json();
}

sources.network/retry.ts:
export function retryDelay(attempt: number, baseMilliseconds: number) {
  return Math.min(baseMilliseconds * 2 ** attempt, 30000);
}

