sources.text/encoding.ts:
export function utf8ByteLength(text: string) {
  return new TextEncoder().encode(text).byteLength;
}

sources.text/lines.ts:
export function lineOffsets(text: string) {
  const offsets = [0];
  for (let index = 0; index < text.length; index++) if (text[index] === '\n') offsets.push(index + 1);
  return offsets;
}

