def cancel_pending_messages(pending_messages, cancelled):
    if cancelled:
        pending_messages.clear()
    return pending_messages

sources.queue/fifo.py:
def take_queue_head(queue):
    if not queue:
        return None
    return queue.pop(0)

sources.images/mime.py:
def image_mime_type(prefix):
    if prefix.startswith(b'\x89PNG'):
        return 'image/png'
    if prefix.startswith(b'\xff\xd8'):
        return 'image/jpeg'
    return None

sources.math/average.py:
def arithmetic_mean(values):
    if not values:
        raise ValueError('empty values')
    return sum(values) / len(values)

sources.jobs/exit.py:
def command_outcome(exit_code, cancelled):
    if cancelled:
        return 'cancelled'
    if exit_code is None:
        return 'unknown'
    return 'success' if exit_code == 0 else 'failed'
